  (* [comment removed for export] *)
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma seg_I_gen : forall (rX : sym_state * list sidecond * scripts) (srX : list expr) (knX : list kentry) (nx : nat),
    sym_exec RSEGS FUELT true STOPT scr0 (SS 0x105db0 srX [] knX nx) [] = rX ->
    snd (fst rX) = [] -> snd (fst (carry (s_log (fst (fst rX))) knX [])) = [] -> log_covered ot_regions (s_log (fst (fst rX))) = true ->
    s_pc (fst (fst rX)) = AMAINEPI ->
    let srY := s_regs (fst (fst rX)) in let knY := fst (fst (carry (s_log (fst (fst rX))) knX [])) in
    sr_get srY 2%bv = spx (-128) -> sr_get srY 4%bv = ELit 0x65d4b0 -> sr_get srY 8%bv = EVar 11 ->
    kread RSEGS knY (ELit 0) 0x11fc58 8 = Some (ELit 0) -> kread RSEGS knY (ELit 0) 0x11fc68 8 = Some (ELit 0) ->
    kread RSEGS knY (ELit 0) 0x11fc38 8 = Some (ELit 0) -> kread RSEGS knY (ELit 0) 0x11fc40 8 = Some (ELit 0) ->
    kread RSEGS knY (ELit 0) 0x11fcbc 4 = Some (ELit 4294967295) ->
    forall vals R M msF mo,
    length vals = nx -> vals_ev vals 0 = sp0 -> vals_ev vals 11 = Z_to_bv 64 2 ->
    regs_ok (ENV vals) srX R -> know_ok RSEGS (ENV vals) M knX -> tst msF mo M ->
    restrict L S msF = mkst R (Z_to_bv 64 0x105db0) M (seg_rom RSEGS) ->
