  Lemma seg_I : forall vals R M msF mo,
    length vals = 291%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 11 = Z_to_bv 64 2 ->
    regs_ok (ENV vals) srI0 R -> know_ok RSEGS (ENV vals) M knI0 -> tst msF mo M ->
