    restrict L S msF = mkst R (Z_to_bv 64 AMEMCPY_RET) M (seg_rom RSEGS) ->
    rdn RSEGS M (Z_to_bv 64 (bv_unsigned sp0 - 585)) (length path) = Some path ->
